CREATE TABLE IF NOT EXISTS stores(slug TEXT PRIMARY KEY, name TEXT, emoji TEXT DEFAULT '⭐', goal INTEGER DEFAULT 6, color TEXT DEFAULT '#7c3aed', pin TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(phone TEXT PRIMARY KEY, name TEXT, age INTEGER, gender TEXT, email TEXT, pin_hash TEXT, fails INTEGER DEFAULT 0, locked_until INTEGER DEFAULT 0, reset_until INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cards(phone TEXT, store TEXT, stamps INTEGER DEFAULT 0, free_redeemed INTEGER DEFAULT 0, joined_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(phone, store));
CREATE INDEX IF NOT EXISTS cards_store ON cards(store);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT, store TEXT, type TEXT, at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS events_lookup ON events(store, phone, id);
CREATE TABLE IF NOT EXISTS hits(k TEXT, w INTEGER, n INTEGER, t INTEGER DEFAULT (unixepoch()), PRIMARY KEY(k, w));
